import type { Airport } from '../types';
import data from './airports.json';

/**
 * Airport lookup over the bundled OurAirports extract (public domain),
 * generated by `scripts/build-airports.mjs`. The Map is built lazily on first use.
 */

type Row = [string, string, string, string, string, number, number, number, string];

let list: Airport[] | null = null;
let byIata: Map<string, Airport> | null = null;
let byIcao: Map<string, Airport> | null = null;

function init(): void {
  if (list) return;
  const rows = (data as unknown as { rows: Row[] }).rows;
  list = rows.map(
    ([iata, icao, name, city, country, lat, lon, elevationM, tz]): Airport => ({
      iata,
      ...(icao ? { icao } : {}),
      name,
      city,
      country,
      lat,
      lon,
      elevationM,
      tz,
    }),
  );
  byIata = new Map();
  byIcao = new Map();
  for (const a of list) {
    byIata.set(a.iata, a);
    if (a.icao) byIcao.set(a.icao, a);
  }
}

export function getAirport(iata: string): Airport | undefined {
  init();
  if (typeof iata !== 'string') return undefined;
  return byIata!.get(iata.trim().toUpperCase());
}

export function isKnownIata(code: string): boolean {
  return getAirport(code) !== undefined;
}

export function allAirports(): Airport[] {
  init();
  return list!;
}

/** Same as getAirport; usable wherever an AirportResolver is expected. */
export const resolveAirport: (iata: string) => Airport | undefined = getAirport;

function norm(s: string): string {
  return s
    .normalize('NFD')
    .replace(/[̀-ͯ]/g, '')
    .toLowerCase();
}

/**
 * Search by IATA (exact first), ICAO (exact), then city / name prefix, then
 * city / name substring. Results are de-duplicated and capped at `limit`.
 */
export function searchAirports(query: string, limit = 10): Airport[] {
  init();
  const q = (query ?? '').trim();
  if (!q || limit <= 0) return [];
  const out: Airport[] = [];
  const seen = new Set<string>();
  const push = (a: Airport | undefined): void => {
    if (a && !seen.has(a.iata) && out.length < limit) {
      seen.add(a.iata);
      out.push(a);
    }
  };

  push(byIata!.get(q.toUpperCase()));
  push(byIcao!.get(q.toUpperCase()));

  const nq = norm(q);
  const all = list!;
  const idx = all.map((a) => [norm(a.city), norm(a.name)] as const);
  // 1. city prefix
  for (let i = 0; i < all.length && out.length < limit; i++) if (idx[i][0].startsWith(nq)) push(all[i]);
  // 2. name prefix
  for (let i = 0; i < all.length && out.length < limit; i++) if (idx[i][1].startsWith(nq)) push(all[i]);
  // 3. substring in city / name
  for (let i = 0; i < all.length && out.length < limit; i++)
    if (idx[i][0].includes(nq) || idx[i][1].includes(nq)) push(all[i]);
  return out;
}
